create or replace function public.admin_get_estate_subscribers(_search text default null,_estate_code text default null) returns table(subscription_id uuid,subscription_number text,estate_name text,estate_code text,user_id uuid,order_id uuid,subscription_status text,payment_plan text,subscription_amount numeric,subscribed_at timestamptz,client_email text,plot_count integer,order_total numeric,amount_paid numeric,order_balance numeric) language plpgsql security definer set search_path=public as $$ begin if not is_admin(auth.uid()) then raise exception 'Admin access required'; end if; return query select es.id,es.subscription_number,es.estate_name,es.estate_code,es.user_id,es.order_id,es.subscription_status,es.payment_plan,es.amount,es.subscribed_at,au.email, greatest(1,coalesce((select sum(coalesce((x->>'quantity')::integer,1)) from jsonb_array_elements(coalesce(o.items,'[]'::jsonb)) x),1))::integer, o.total_amount, o.amount_paid, o.balance from public.estate_subscriptions es left join public.orders o on o.id=es.order_id left join auth.users au on au.id=es.user_id where (_search is null or _search='' or es.subscription_number ilike '%'||_search||'%' or es.estate_name ilike '%'||_search||'%' or au.email ilike '%'||_search||'%') and (_estate_code is null or _estate_code='' or es.estate_code=_estate_code) order by es.created_at desc; end; $$; revoke all on function public.admin_get_estate_subscribers(text,text) from public; grant execute on function public.admin_get_estate_subscribers(text,text) to authenticated;
